import { afterEach, describe, expect, it } from "vitest";

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { spawnSync } = require("node:child_process");

const roots: string[] = [];
const cli = path.join(process.cwd(), "native", "cli.cjs");
const accountId = "0123456789abcdef0123456789abcdef";

function environment() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "surf-semantic-auth-cli-"));
  roots.push(root);
  const {
    TYPESAFE_API_KEY: _typesafe,
    CLOUDFLARE_ACCOUNT_ID: _account,
    CLOUDFLARE_API_TOKEN: _token,
    SURF_SEMANTIC_MODEL: _model,
    ...baseEnvironment
  } = process.env;
  const env = {
    ...baseEnvironment,
    XDG_CONFIG_HOME: path.join(root, "config"),
    SURF_SOCKET: path.join(root, "missing.sock"),
  };
  return env;
}

function run(args: string[], env: Record<string, string>, input?: string) {
  return spawnSync(process.execPath, [cli, ...args], {
    cwd: process.cwd(),
    env,
    input,
    encoding: "utf8",
  });
}

afterEach(() => {
  for (const root of roots.splice(0)) {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

describe("semantic auth CLI", () => {
  it("sets, reports, and clears the shared credential without contacting the missing host", () => {
    const env = environment();
    const set = run(["semantic", "auth", "set"], env, "black-box-secret\n");
    expect(set.status).toBe(0);
    expect(set.stdout).toContain("typesafe: shared-store (sha256:");
    expect(`${set.stdout}${set.stderr}`).not.toContain("black-box-secret");

    const file = path.join(env.XDG_CONFIG_HOME, "typesafe", "credentials.json");
    expect(JSON.parse(fs.readFileSync(file, "utf8"))).toEqual({
      version: 1,
      apiKey: "black-box-secret",
    });
    if (process.platform !== "win32") {
      expect(fs.statSync(path.dirname(file)).mode & 0o777).toBe(0o700);
      expect(fs.statSync(file).mode & 0o777).toBe(0o600);
    }

    const status = run(["semantic.auth.status", "--json"], env);
    expect(status.status).toBe(0);
    expect(JSON.parse(status.stdout)).toEqual({
      typesafe: { source: "shared-store", fingerprint: expect.stringMatching(/^sha256:/) },
      cloudflare: { source: "not-configured" },
    });
    expect(status.stdout).not.toContain("black-box-secret");

    const clear = run(["semantic", "auth", "clear"], env);
    expect(clear.status).toBe(0);
    expect(clear.stdout).toContain("Shared TypeSafe credential cleared for all clients.");
    expect(clear.stdout).toContain("No stored Cloudflare credential found.");
    expect(fs.existsSync(file)).toBe(false);
  });

  it("stores Cloudflare credentials from stdin and reports fingerprints only", () => {
    const env = environment();
    const set = run(
      ["semantic", "auth", "set", "--provider", "cloudflare"],
      env,
      `${accountId}\ncloudflare-black-box-token\n`,
    );
    expect(set.status).toBe(0);
    expect(set.stdout).toMatch(/^cloudflare: stored \(sha256:[0-9a-f]{12}\)$/m);

    const status = run(["semantic", "auth", "status"], env);
    expect(status.status).toBe(0);
    expect(status.stdout.trim().split("\n")).toEqual([
      "typesafe: not-configured",
      expect.stringMatching(/^cloudflare: stored \(sha256:[0-9a-f]{12}\)$/),
    ]);
    const only = run(["semantic", "auth", "status", "--provider", "cloudflare", "--json"], env);
    expect(Object.keys(JSON.parse(only.stdout))).toEqual(["cloudflare"]);
    for (const output of [set, status, only]) {
      expect(`${output.stdout}${output.stderr}`).not.toContain("cloudflare-black-box-token");
      expect(`${output.stdout}${output.stderr}`).not.toContain(accountId);
    }

    const clear = run(["semantic", "auth", "clear", "--provider", "cloudflare"], env);
    expect(clear.status).toBe(0);
    expect(clear.stdout.trim()).toBe("Stored Cloudflare credential cleared.");
    expect(
      fs.existsSync(path.join(env.XDG_CONFIG_HOME, "surf", "cloudflare-credentials.json")),
    ).toBe(false);
  });

  it("uses the environment override and rejects argv secrets and browser flags locally", () => {
    const base = environment();
    const env = { ...base, TYPESAFE_API_KEY: "environment-secret" };
    const status = run(["semantic", "auth", "status"], env);
    expect(status.status).toBe(0);
    expect(status.stdout).toContain("typesafe: environment (sha256:");
    expect(status.stdout).not.toContain("environment-secret");

    for (const args of [
      ["semantic", "auth", "set", "argv-secret"],
      ["semantic", "auth", "status", "--tab-id", "1"],
      ["semantic", "auth", "set", "--api-key", "argv-secret"],
      ["semantic", "auth", "set", "--provider", "argv-secret"],
    ]) {
      const result = run(args, base);
      expect(result.status).toBe(1);
      expect(result.stderr).toContain("not secrets or browser targeting flags");
      expect(result.stderr).not.toContain("argv-secret");
    }
  });
});

import { afterEach, describe, expect, it } from "vitest";

const { Buffer } = require("node:buffer");
const { EventEmitter } = require("node:events");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { PassThrough, Readable } = require("node:stream");
const credentials = require("../../native/semantic-credentials.cjs");

const roots: string[] = [];

class FakeTty extends EventEmitter {
  isTTY = true;
  isRaw = false;
  rawCalls: boolean[] = [];
  setRawMode(value: boolean) {
    this.isRaw = value;
    this.rawCalls.push(value);
  }
  resume() {
    /* EventEmitter test double. */
  }
  pause() {
    /* EventEmitter test double. */
  }
}

function testEnv(extra: Record<string, string> = {}) {
  const parent = fs.mkdtempSync(path.join(os.tmpdir(), "surf-semantic-credentials-"));
  roots.push(parent);
  return {
    XDG_CONFIG_HOME: path.join(parent, "config"),
    SURF_STATE_DIR: path.join(parent, "unrelated-surf-state"),
    ...extra,
  };
}

afterEach(() => {
  for (const root of roots.splice(0)) {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

describe("TypeSafe credential store", () => {
  it("prefers a nonblank environment key and reports only its source and fingerprint", () => {
    const env = testEnv({ TYPESAFE_API_KEY: "environment-secret" });
    credentials.storeTypeSafeCredential("stored-secret", env);

    const resolved = credentials.resolveTypeSafeCredential(env);
    expect(resolved).toEqual({
      apiKey: "environment-secret",
      source: "environment",
      fingerprint: credentials.fingerprintApiKey("environment-secret"),
    });
    const status = credentials.credentialStatus(env, "typesafe");
    expect(status).toEqual({
      typesafe: { source: "environment", fingerprint: resolved.fingerprint },
    });
    expect(JSON.stringify(status)).not.toContain("environment-secret");
  });

  it("falls back from a blank environment value to the shared store", () => {
    const env = testEnv({ TYPESAFE_API_KEY: " \t " });
    const stored = credentials.storeTypeSafeCredential("stored-secret", env);

    expect(credentials.resolveTypeSafeCredential(env)).toEqual({
      apiKey: "stored-secret",
      source: "shared-store",
      fingerprint: stored.fingerprint,
    });
  });

  it("writes atomically under private directories and rejects symlinked credential paths", () => {
    const env = testEnv();
    credentials.storeTypeSafeCredential("first-secret", env);
    credentials.storeTypeSafeCredential("second-secret", env);
    const { root, filePath } = credentials.credentialLocation(env);

    expect(JSON.parse(fs.readFileSync(filePath, "utf8"))).toEqual({
      version: 1,
      apiKey: "second-secret",
    });
    expect(fs.statSync(root).mode & 0o777).toBe(0o700);
    expect(fs.statSync(filePath).mode & 0o777).toBe(0o600);
    expect(
      fs.readdirSync(path.dirname(filePath)).filter((name: string) => name.endsWith(".tmp")),
    ).toEqual([]);

    fs.unlinkSync(filePath);
    const target = path.join(path.dirname(root), "target.json");
    fs.writeFileSync(target, JSON.stringify({ version: 1, apiKey: "stolen" }), { mode: 0o600 });
    fs.symlinkSync(target, filePath);
    expect(() => credentials.resolveTypeSafeCredential(env)).toThrow(/symbolic link/);
    expect(() => credentials.storeTypeSafeCredential("replacement", env)).toThrow(/symbolic link/);
    expect(() => credentials.clearStoredTypeSafeCredential(env)).toThrow(/symbolic link/);
  });

  it("clears only the stored file without creating state directories", () => {
    const env = testEnv({ TYPESAFE_API_KEY: "environment-secret" });
    const { root, filePath } = credentials.credentialLocation(env);
    expect(credentials.clearStoredTypeSafeCredential(env)).toBe(false);
    expect(fs.existsSync(root)).toBe(false);

    credentials.storeTypeSafeCredential("stored-secret", env);
    const sibling = path.join(root, "other.json");
    fs.writeFileSync(sibling, "keep", { mode: 0o600 });
    expect(credentials.clearStoredTypeSafeCredential(env)).toBe(true);
    expect(fs.existsSync(filePath)).toBe(false);
    expect(fs.readFileSync(sibling, "utf8")).toBe("keep");
    expect(credentials.credentialStatus(env, "typesafe").typesafe.source).toBe("environment");
  });

  it("resolves the provider-neutral shared path independently of Surf state", () => {
    expect(
      credentials.credentialLocation(
        { XDG_CONFIG_HOME: "/xdg", SURF_STATE_DIR: "/surf" },
        { platform: "linux", homeDir: "/home/test" },
      ),
    ).toEqual({ root: "/xdg/typesafe", filePath: "/xdg/typesafe/credentials.json" });
    expect(
      credentials.credentialLocation(
        { SURF_STATE_DIR: "/surf" },
        { platform: "darwin", homeDir: "/Users/test" },
      ),
    ).toEqual({
      root: "/Users/test/.config/typesafe",
      filePath: "/Users/test/.config/typesafe/credentials.json",
    });
    expect(
      credentials.credentialLocation(
        { APPDATA: "C:\\Users\\test\\AppData\\Roaming", SURF_STATE_DIR: "C:\\surf" },
        { platform: "win32", homeDir: "C:\\Users\\test" },
      ),
    ).toEqual({
      root: "C:\\Users\\test\\AppData\\Roaming\\TypeSafe",
      filePath: "C:\\Users\\test\\AppData\\Roaming\\TypeSafe\\credentials.json",
    });
  });

  it("returns not-configured without creating state and rejects malformed or public files", () => {
    const env = testEnv();
    const { root, filePath } = credentials.credentialLocation(env);
    expect(credentials.credentialStatus(env)).toEqual({
      typesafe: { source: "not-configured" },
      cloudflare: { source: "not-configured" },
    });
    expect(fs.existsSync(root)).toBe(false);

    fs.mkdirSync(path.dirname(filePath), { recursive: true, mode: 0o700 });
    fs.writeFileSync(filePath, JSON.stringify({ version: 1, apiKey: "secret" }), { mode: 0o644 });
    expect(() => credentials.credentialStatus(env)).toThrow(/permissions are too broad/);
    fs.chmodSync(filePath, 0o600);
    fs.writeFileSync(filePath, JSON.stringify({ version: 2, apiKey: "secret" }));
    expect(() => credentials.credentialStatus(env)).toThrow(/credential is invalid/);
  });
});

describe("malformed stored credentials", () => {
  it.each([
    ["typesafe", "credentialLocation", "TypeSafe", '{"version":1,"apiKey":SENTINELSECRET}'],
    [
      "cloudflare",
      "cloudflareCredentialLocation",
      "Cloudflare",
      `{"version":1,"accountId":"${"0".repeat(32)}","apiToken":SENTINELSECRET}`,
    ],
  ])(
    "reports a malformed %s record without echoing its contents",
    (provider, location, label, text) => {
      const env = testEnv();
      const { filePath } = credentials[location](env);
      fs.mkdirSync(path.dirname(filePath), { recursive: true, mode: 0o700 });
      fs.writeFileSync(filePath, text, { mode: 0o600 });
      let message = "";
      try {
        credentials.credentialStatus(env, provider);
      } catch (error) {
        message = (error as Error).message;
      }
      expect(message).toBe(`stored ${label} credential is invalid`);
    },
  );
});

describe("TypeSafe credential input", () => {
  it("accepts exactly one bounded stdin line without writing the secret", async () => {
    const output = new PassThrough();
    let written = "";
    output.on("data", (chunk: { toString(): string }) => {
      written += chunk.toString();
    });

    await expect(
      credentials.readTypeSafeApiKey({ input: Readable.from(["piped-secret\n"]), output }),
    ).resolves.toBe("piped-secret");
    expect(written).toBe("");
    await expect(
      credentials.readTypeSafeApiKey({ input: Readable.from(["one\ntwo\n"]), output }),
    ).rejects.toThrow(/one line/);
    await expect(
      credentials.readTypeSafeApiKey({ input: Readable.from([" \n"]), output }),
    ).rejects.toThrow(/must not be blank/);
    await expect(
      credentials.readTypeSafeApiKey({
        input: Readable.from(["x".repeat(credentials.MAX_API_KEY_BYTES + 1)]),
        output,
      }),
    ).rejects.toThrow(/exceeds/);
  });

  it("uses raw TTY input, handles editing, and never echoes the key", async () => {
    const input = new FakeTty();
    let written = "";
    const output = {
      write(value: string) {
        written += value;
        return true;
      },
    };
    const pending = credentials.readTypeSafeApiKey({ input, output });
    input.emit("data", Buffer.from("secrex\u007ft\r"));

    await expect(pending).resolves.toBe("secret");
    expect(input.rawCalls).toEqual([true, false]);
    expect(written).toBe("TypeSafe API key: \n");
    expect(written).not.toContain("secret");
  });

  it("restores raw mode and removes every temporary signal listener when interrupted", async () => {
    const input = new FakeTty();
    const signalSource = new EventEmitter();
    const pending = credentials.readTypeSafeApiKey({
      input,
      output: { write: () => true },
      signalSource,
    });
    expect(
      ["SIGINT", "SIGTERM", "SIGHUP"].map((signal) => signalSource.listenerCount(signal)),
    ).toEqual([1, 1, 1]);
    signalSource.emit("SIGTERM");
    await expect(pending).rejects.toThrow("interrupted by SIGTERM");
    expect(input.rawCalls).toEqual([true, false]);
    expect(
      ["SIGINT", "SIGTERM", "SIGHUP"].map((signal) => signalSource.listenerCount(signal)),
    ).toEqual([0, 0, 0]);
  });
});

const ACCOUNT_ID = "0123456789abcdef0123456789abcdef";
const OTHER_ACCOUNT_ID = "fedcba9876543210fedcba9876543210";

function setCloudflareFromPipe(env: Record<string, string>, text: string) {
  return credentials.setCloudflareCredentialFromInput({
    input: Readable.from([text]),
    output: { write: () => true },
    env,
  });
}

describe("Cloudflare credential store", () => {
  it("prefers complete environment credentials and rejects a partial environment by name", async () => {
    const env = testEnv({
      CLOUDFLARE_ACCOUNT_ID: OTHER_ACCOUNT_ID,
      CLOUDFLARE_API_TOKEN: "environment-token",
    });
    await setCloudflareFromPipe(env, `${ACCOUNT_ID}\nstored-token\n`);

    expect(credentials.resolveCloudflareCredential(env)).toEqual({
      accountId: OTHER_ACCOUNT_ID,
      apiToken: "environment-token",
      source: "environment",
      fingerprint: credentials.fingerprintApiKey("environment-token"),
    });
    expect(() =>
      credentials.resolveCloudflareCredential({ ...env, CLOUDFLARE_API_TOKEN: " " }),
    ).toThrow(/^CLOUDFLARE_API_TOKEN is not set/);
    expect(() =>
      credentials.resolveCloudflareCredential({ ...env, CLOUDFLARE_ACCOUNT_ID: "" }),
    ).toThrow(/^CLOUDFLARE_ACCOUNT_ID is not set/);
    expect(() =>
      credentials.resolveCloudflareCredential({ ...env, CLOUDFLARE_ACCOUNT_ID: "not-an-account" }),
    ).toThrow(/account id must be 32/);
    expect(
      credentials.resolveCloudflareCredential({
        ...env,
        CLOUDFLARE_ACCOUNT_ID: " ",
        CLOUDFLARE_API_TOKEN: "",
      }),
    ).toMatchObject({ accountId: ACCOUNT_ID, apiToken: "stored-token", source: "stored" });
  });

  it("stores piped credentials in a private Surf file separate from TypeSafe and clears it", async () => {
    const env = testEnv();
    const { root, filePath } = credentials.cloudflareCredentialLocation(env);
    expect(root).toBe(path.join(env.XDG_CONFIG_HOME, "surf"));
    expect(credentials.resolveCloudflareCredential(env)).toBeNull();
    expect(credentials.clearStoredCloudflareCredential(env)).toBe(false);
    expect(fs.existsSync(root)).toBe(false);

    await expect(setCloudflareFromPipe(env, `${ACCOUNT_ID}\r\nstored-token\r\n`)).resolves.toEqual({
      source: "stored",
      fingerprint: credentials.fingerprintApiKey("stored-token"),
    });
    expect(JSON.parse(fs.readFileSync(filePath, "utf8"))).toEqual({
      version: 1,
      accountId: ACCOUNT_ID,
      apiToken: "stored-token",
    });
    expect(fs.statSync(root).mode & 0o777).toBe(0o700);
    expect(fs.statSync(filePath).mode & 0o777).toBe(0o600);
    expect(fs.existsSync(credentials.credentialLocation(env).root)).toBe(false);
    expect(credentials.resolveCloudflareCredential(env)).toEqual({
      accountId: ACCOUNT_ID,
      apiToken: "stored-token",
      source: "stored",
      fingerprint: credentials.fingerprintApiKey("stored-token"),
    });

    expect(credentials.clearStoredCloudflareCredential(env)).toBe(true);
    expect(fs.existsSync(filePath)).toBe(false);
    expect(credentials.resolveCloudflareCredential(env)).toBeNull();
  });

  it("rejects invalid stored records and malformed piped input without storing anything", async () => {
    const env = testEnv();
    const { filePath } = credentials.cloudflareCredentialLocation(env);
    for (const text of [`${ACCOUNT_ID}\n`, `${ACCOUNT_ID}\ntoken\nextra\n`, "ABC\ntoken\n"]) {
      await expect(setCloudflareFromPipe(env, text)).rejects.toThrow(/two lines|account id/);
    }
    await expect(setCloudflareFromPipe(env, `${ACCOUNT_ID}\n \n`)).rejects.toThrow(
      /must not be blank/,
    );
    expect(fs.existsSync(filePath)).toBe(false);

    fs.mkdirSync(path.dirname(filePath), { recursive: true, mode: 0o700 });
    fs.writeFileSync(filePath, JSON.stringify({ version: 1, accountId: "bad", apiToken: "t" }), {
      mode: 0o600,
    });
    expect(() => credentials.resolveCloudflareCredential(env)).toThrow(
      "stored Cloudflare credential is invalid",
    );
  });

  it("echoes the account id on a TTY but keeps the token hidden", async () => {
    const env = testEnv();
    const input = new FakeTty();
    let written = "";
    const output = {
      write(value: string) {
        written += value;
        return true;
      },
    };
    const pending = credentials.setCloudflareCredentialFromInput({ input, output, env });
    input.emit("data", Buffer.from(`${ACCOUNT_ID}\r`));
    await new Promise((resolve) => setTimeout(resolve, 0));
    input.emit("data", Buffer.from("tty-token\r"));

    await expect(pending).resolves.toMatchObject({ source: "stored" });
    expect(written).toBe(`Cloudflare account id: ${ACCOUNT_ID}\nCloudflare API token: \n`);
    expect(input.rawCalls).toEqual([true, false, true, false]);
    expect(credentials.resolveCloudflareCredential(env)).toMatchObject({ apiToken: "tty-token" });
  });
});

import { afterEach, describe, expect, it } from "vitest";

declare const require: (moduleName: string) => unknown;
declare const process: { pid: number };
type ByteBuffer = { toString(encoding?: string): string };
declare const Buffer: { alloc(size: number, fill?: number): ByteBuffer };
const fs = require("node:fs") as {
  mkdtempSync(prefix: string): string;
  readFileSync(filePath: string, encoding: string): string;
  rmSync(filePath: string, options: { recursive?: boolean; force?: boolean }): void;
  statSync(filePath: string): { mode: number };
  symlinkSync(target: string, linkPath: string): void;
};
const os = require("node:os") as { tmpdir(): string };
const path = require("node:path") as { join(...parts: string[]): string };

const auth = require("../../native/remote-auth.cjs") as {
  authorizeClient(
    label: string,
    outputPath: string,
    stateDir: string,
  ): { id: string; output: string };
  canonicalTranscript(
    role: string,
    clientId: string,
    clientNonce: string,
    serverNonce: string,
    clientPublicKey: string,
    hostPublicKey: string,
  ): ByteBuffer;
  ensureHostIdentity(stateDir: string): { publicKey: string; privateKey: object };
  listClients(stateDir: string): Array<{ id: string; label: string }>;
  loadCredential(filePath: string): {
    clientId: string;
    label: string;
    hostPublicKey: string;
    publicKey: string;
    privateKey: object;
  };
  loadRegistry(stateDir: string): { clients: Array<Record<string, unknown>> };
  revokeClient(label: string, stateDir: string): void;
  signChallenge(
    host: { publicKey: string; privateKey: object },
    clientId: string,
    clientNonce: string,
    serverNonce: string,
    clientPublicKey: string,
  ): string;
  signProof(
    credential: { clientId: string; publicKey: string; hostPublicKey: string; privateKey: object },
    clientNonce: string,
    serverNonce: string,
  ): string;
  verifyChallenge(
    credential: { clientId: string; publicKey: string; hostPublicKey: string },
    challenge: Record<string, unknown>,
  ): boolean;
  verifyProof(
    client: { id: string; publicKey: string },
    hostPublicKey: string,
    clientNonce: string,
    serverNonce: string,
    proof: string,
  ): boolean;
};

const tempDirs: string[] = [];

afterEach(() => {
  for (const dir of tempDirs.splice(0)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

function createState() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "surf-remote-auth-"));
  tempDirs.push(dir);
  return dir;
}

describe("remote authentication state", () => {
  it("creates a private state directory, public-only registry, and non-overwriting credential", () => {
    const stateDir = createState();
    const output = path.join(stateDir, "client.json");
    const client = auth.authorizeClient("alice", output, stateDir);

    expect(client.id).toMatch(/^[a-f0-9]{32}$/);
    expect(fs.statSync(stateDir).mode & 0o777).toBe(0o700);
    expect(fs.statSync(output).mode & 0o777).toBe(0o600);
    expect(auth.loadRegistry(stateDir).clients[0]).not.toHaveProperty("privateKey");
    expect(JSON.parse(fs.readFileSync(output, "utf8"))).toHaveProperty("privateKey");
    expect(() =>
      auth.authorizeClient("alice", path.join(stateDir, "second.json"), stateDir),
    ).toThrow("already exists");
    expect(() => auth.authorizeClient("bob", output, stateDir)).toThrow("already exists");
  });

  it("rejects unsafe labels, symlinked state, and symlinked credential output", () => {
    const stateDir = createState();
    expect(() =>
      auth.authorizeClient("bad label", path.join(stateDir, "client.json"), stateDir),
    ).toThrow("label");
    const linkedOutput = path.join(stateDir, "linked.json");
    fs.symlinkSync(path.join(stateDir, "missing.json"), linkedOutput);
    expect(() => auth.authorizeClient("alice", linkedOutput, stateDir)).toThrow("symbolic link");

    const linkedState = path.join(os.tmpdir(), `surf-remote-state-link-${process.pid}`);
    fs.rmSync(linkedState, { force: true });
    fs.symlinkSync(stateDir, linkedState);
    tempDirs.push(linkedState);
    expect(() =>
      auth.authorizeClient("alice", path.join(linkedState, "client.json"), linkedState),
    ).toThrow("symbolic link");
  });

  it("lists and revokes clients without retaining private keys in the registry", () => {
    const stateDir = createState();
    auth.authorizeClient("alice", path.join(stateDir, "alice.json"), stateDir);
    auth.authorizeClient("bob", path.join(stateDir, "bob.json"), stateDir);
    expect(auth.listClients(stateDir).map((client) => client.label)).toEqual(["alice", "bob"]);
    auth.revokeClient("alice", stateDir);
    expect(auth.listClients(stateDir).map((client) => client.label)).toEqual(["bob"]);
    expect(() => auth.revokeClient("alice", stateDir)).toThrow("not found");
    expect(fs.readFileSync(path.join(stateDir, "remote-clients.json"), "utf8")).not.toContain(
      "privateKey",
    );
  });

  it("binds signatures to both nonces and the pinned host identity", () => {
    const stateDir = createState();
    auth.authorizeClient("alice", path.join(stateDir, "alice.json"), stateDir);
    const credential = auth.loadCredential(path.join(stateDir, "alice.json"));
    const host = auth.ensureHostIdentity(stateDir);
    const client = auth.loadRegistry(stateDir).clients[0] as { id: string; publicKey: string };
    const clientNonce = Buffer.alloc(32, 1).toString("base64");
    const serverNonce = Buffer.alloc(32, 2).toString("base64");
    const challenge = {
      type: "auth_challenge",
      version: 1,
      clientId: credential.clientId,
      clientNonce,
      serverNonce,
      hostPublicKey: credential.hostPublicKey,
      signature: auth.signChallenge(
        host,
        credential.clientId,
        clientNonce,
        serverNonce,
        credential.publicKey,
      ),
    };

    expect(auth.verifyChallenge(credential, challenge)).toBe(true);
    expect(
      auth.verifyChallenge(credential, {
        ...challenge,
        serverNonce: Buffer.alloc(32, 3).toString("base64"),
      }),
    ).toBe(false);
    const proof = auth.signProof(credential, clientNonce, serverNonce);
    expect(auth.verifyProof(client, host.publicKey, clientNonce, serverNonce, proof)).toBe(true);
    expect(
      auth.verifyProof(
        client,
        host.publicKey,
        clientNonce,
        Buffer.alloc(32, 3).toString("base64"),
        proof,
      ),
    ).toBe(false);
    expect(
      auth.canonicalTranscript(
        "client",
        credential.clientId,
        clientNonce,
        serverNonce,
        credential.publicKey,
        credential.hostPublicKey,
      ),
    ).toBeInstanceOf(Buffer);
  });
});

import { afterEach, describe, expect, it } from "vitest";

const { mkdtempSync, rmSync, writeFileSync } = require("node:fs");
const { tmpdir } = require("node:os");
const { join } = require("node:path");

const { BrowserSessionStore, parseDurationMs, validateSessionName } =
  require("../../native/browser-session-store.cjs") as {
    BrowserSessionStore: new (options: {
      filePath: string;
      root: string;
      now?: () => string;
    }) => any;
    parseDurationMs(value: string | number): number;
    validateSessionName(name: string): string;
  };

const roots: string[] = [];

afterEach(() => {
  for (const root of roots.splice(0)) {
    rmSync(root, { recursive: true, force: true });
  }
});

function store() {
  const root = mkdtempSync(join(tmpdir(), "surf-browser-sessions-"));
  roots.push(root);
  return {
    root,
    store: new BrowserSessionStore({
      root,
      filePath: join(root, "browser-sessions.json"),
      now: () => "2026-08-18T00:00:00.000Z",
    }),
  };
}

const identity = { browserInstanceId: "browser-a", browserEpoch: "epoch-a" };

describe("BrowserSessionStore", () => {
  it("parses explicit cleanup durations and plain seconds", () => {
    expect(parseDurationMs("30s")).toBe(30_000);
    expect(parseDurationMs("5m")).toBe(300_000);
    expect(parseDurationMs("1h")).toBe(3_600_000);
    expect(parseDurationMs("2d")).toBe(172_800_000);
    expect(parseDurationMs(45)).toBe(45_000);
    expect(() => parseDurationMs("1w")).toThrow(/duration/i);
    expect(() => parseDurationMs(0)).toThrow(/positive/i);
    expect(() => parseDurationMs(undefined as never)).toThrow(/requires/i);
  });

  it("persists case-insensitive named bindings without changing their display name", () => {
    const { store: sessions } = store();
    const created = sessions.create(identity, "Research", {
      tabId: 11,
      windowId: 22,
      mode: "window",
      ownership: "surf-created",
      lastUrl: "https://example.com/",
    });

    expect(created.name).toBe("Research");
    expect(created.lastAccessedAt).toBe("2026-08-18T00:00:00.000Z");
    expect(sessions.get(identity, "research")).toMatchObject({ tabId: 11, windowId: 22 });
    expect(() => sessions.create(identity, "RESEARCH", { tabId: 99 })).toThrow(/already exists/i);
  });

  it("marks a removed tab stale while retaining its last URL for recovery", () => {
    const { store: sessions } = store();
    sessions.create(identity, "research", {
      tabId: 11,
      windowId: 22,
      mode: "window",
      ownership: "surf-created",
      lastUrl: "https://example.com/recover",
    });

    expect(sessions.invalidateByTab(identity, 11)).toBe(true);
    expect(sessions.get(identity, "research")).toMatchObject({
      invalidReason: "tab_gone",
      lastUrl: "https://example.com/recover",
    });
  });

  it("replaces stale bindings while preserving the binding ID and creation time", () => {
    const { store: sessions } = store();
    const first = sessions.create(identity, "research", {
      tabId: 11,
      windowId: 22,
      mode: "window",
      ownership: "surf-created",
    });
    sessions.invalidateByTab(identity, 11);
    const second = sessions.replace(identity, "research", {
      tabId: 33,
      windowId: 44,
      mode: "window",
      ownership: "surf-created",
    });

    expect(second.bindingId).toBe(first.bindingId);
    expect(second.createdAt).toBe(first.createdAt);
    expect(second.invalidReason).toBeUndefined();
    expect(second.tabId).toBe(33);
  });

  it("persists session frame context across host store instances", () => {
    const { root, store: sessions } = store();
    const filePath = join(root, "browser-sessions.json");
    sessions.create(identity, "research", {
      tabId: 11,
      windowId: 22,
      mode: "window",
      ownership: "surf-created",
    });
    sessions.update(identity, "research", {
      frameContext: {
        frameId: 9,
        tabId: 11,
        windowId: 22,
        browserEpoch: identity.browserEpoch,
        url: "https://example.com/frame",
      },
    });

    const reloaded = new BrowserSessionStore({
      root,
      filePath,
      now: () => "2026-08-18T00:00:00.000Z",
    });
    expect(reloaded.get(identity, "research")).toMatchObject({
      frameContext: { frameId: 9, tabId: 11, browserEpoch: "epoch-a" },
    });
  });

  it("persists named-tab aliases in host state and removes them with their tab", () => {
    const { store: sessions } = store();
    sessions.setNamedTab(identity, "dashboard", {
      tabId: 77,
      windowId: 8,
      lastUrl: "https://example.com/dashboard",
    });

    expect(sessions.getNamedTab(identity, "DASHBOARD")).toMatchObject({ tabId: 77 });
    sessions.invalidateByTab(identity, 77);
    expect(sessions.getNamedTab(identity, "dashboard")).toBeNull();
  });

  it("fails closed on malformed private state", () => {
    const { root, store: sessions } = store();
    writeFileSync(join(root, "browser-sessions.json"), "{not-json", { mode: 0o600 });
    expect(() => sessions.list(identity)).toThrow(/failed to read browser sessions/i);
  });

  it("validates agent-safe session names", () => {
    expect(validateSessionName("repo.agent-1")).toBe("repo.agent-1");
    expect(() => validateSessionName("has spaces")).toThrow(/session name/i);
    expect(() => validateSessionName("/escape")).toThrow(/session name/i);
  });
});

import { afterEach, beforeEach, describe, expect, it } from "vitest";

declare const require: (moduleName: string) => any;

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { acquireBrowserLock, getBrowserLockDir } = require("../../native/browser-lock.cjs");

describe("browser lock", () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "surf-browser-lock-test-"));
  });

  afterEach(() => {
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  it("creates and releases a per-socket lock", () => {
    const lock = acquireBrowserLock("/tmp/surf.sock", tempDir);
    const lockDir = getBrowserLockDir("/tmp/surf.sock", tempDir);

    expect(lock.lockDir).toBe(lockDir);
    expect(fs.existsSync(path.join(lockDir, "owner.json"))).toBe(true);

    lock.release();

    expect(fs.existsSync(lockDir)).toBe(false);
  });

  it("uses independent lock directories for different sockets", () => {
    const first = acquireBrowserLock("/tmp/surf-agent-a.sock", tempDir);
    const second = acquireBrowserLock("/tmp/surf-agent-b.sock", tempDir);

    expect(first.lockDir).not.toBe(second.lockDir);

    first.release();
    second.release();
  });

  it("removes stale locks owned by dead processes before acquiring", () => {
    const lockDir = getBrowserLockDir("/tmp/surf.sock", tempDir);
    fs.mkdirSync(lockDir);
    fs.writeFileSync(
      path.join(lockDir, "owner.json"),
      JSON.stringify({ pid: -1, token: "dead-owner", socketPath: "/tmp/surf.sock" }),
    );
    const staleTime = new Date(Date.now() - 60_000);
    fs.utimesSync(lockDir, staleTime, staleTime);

    const lock = acquireBrowserLock("/tmp/surf.sock", tempDir, { staleMs: 1 });

    expect(lock.lockDir).toBe(lockDir);
    expect(JSON.parse(fs.readFileSync(path.join(lockDir, "owner.json"), "utf8")).pid).toBe(
      process.pid,
    );

    lock.release();
  });

  it("does not steal an old lock from a live process", () => {
    const lockDir = getBrowserLockDir("/tmp/surf.sock", tempDir);
    fs.mkdirSync(lockDir);
    fs.writeFileSync(
      path.join(lockDir, "owner.json"),
      JSON.stringify({ pid: process.pid, token: "live-owner", socketPath: "/tmp/surf.sock" }),
    );
    const staleTime = new Date(Date.now() - 60_000);
    fs.utimesSync(lockDir, staleTime, staleTime);

    expect(() =>
      acquireBrowserLock("/tmp/surf.sock", tempDir, {
        timeoutMs: -1,
        staleMs: 1,
        sleep: () => undefined,
      }),
    ).toThrow("Timed out waiting for browser lock");
    expect(fs.existsSync(path.join(lockDir, "owner.json"))).toBe(true);
  });

  it("does not release a replacement lock owned by another process", () => {
    const first = acquireBrowserLock("/tmp/surf.sock", tempDir);
    const lockDir = first.lockDir;
    fs.rmSync(lockDir, { recursive: true, force: true });
    fs.mkdirSync(lockDir);
    fs.writeFileSync(
      path.join(lockDir, "owner.json"),
      JSON.stringify({ pid: process.pid, token: "replacement", socketPath: "/tmp/surf.sock" }),
    );

    first.release();

    expect(fs.existsSync(path.join(lockDir, "owner.json"))).toBe(true);
  });

  it("times out while a fresh lock is held", () => {
    const held = acquireBrowserLock("/tmp/surf.sock", tempDir);

    expect(() =>
      acquireBrowserLock("/tmp/surf.sock", tempDir, {
        timeoutMs: -1,
        staleMs: 60_000,
        sleep: () => undefined,
      }),
    ).toThrow("Timed out waiting for browser lock");

    held.release();
  });
});

